  const src = [
    [160+Math.sin(t*0.6)*100, 24+Math.cos(t*0.4)*18, 0.08*P(0)/2, 2.0],
    [320+Math.cos(t*0.5)*100, 72+Math.sin(t*0.7)*18, 0.1*P(1)/3, 1.7],
